window.currentTrainingBlock='A';data.blockNames??={};let activeExercise=0,seriesEntries=[];
function blockTitle(){return data.blockNames[student]?.[window.currentTrainingBlock]||`Treino ${window.currentTrainingBlock}`}
function trainingBlocks(){return [...new Set(['A','B','C',...Object.keys(data.alternatePlans?.[student]||{}),...Object.keys(data.blockNames?.[student]||{})])].sort()}
function blockChooser(){return `<section class="card program-selector"><div class="row"><div><span class="eyebrow">SEU PROGRAMA DE TREINO</span><h2>${esc(blockTitle())}</h2></div>${role==='personal'?'<button onclick="renameTrainingBlock()">Nomear treino</button>':''}</div><div class="program-tabs" role="tablist" aria-label="Divisões do treino">${trainingBlocks().map(block=>`<button role="tab" aria-selected="${window.currentTrainingBlock===block}" class="${window.currentTrainingBlock===block?'primary':''}" onclick="chooseTrainingBlock('${block}')" ${workoutStarted?'disabled':''}>Treino ${block}</button>`).join('')}</div><p class="note">${workoutStarted?'Finalize a sessão para mudar de treino.':'Escolha a divisão indicada pelo seu personal.'}</p></section>`}
window.chooseTrainingBlock=block=>{if(!trainingBlocks().includes(block)||workoutStarted)return;window.currentTrainingBlock=block;activeExercise=0;done.clear();render()};
window.renameTrainingBlock=()=>{if(role!=='personal')return;modal(`<h2>Nome do treino ${window.currentTrainingBlock}</h2><form id="blockForm"><label>Nome<input name="title" value="${esc(blockTitle())}" maxlength="80" required></label><button class="primary">Salvar nome</button></form>`);$('#blockForm').onsubmit=e=>{e.preventDefault();const title=new FormData(e.target).get('title').trim();if(!title)return;data.blockNames[student]??={};data.blockNames[student][window.currentTrainingBlock]=title;save();$('#modal').close();render()}};
function seriesUnit(x){return /min|seg|["'’]/i.test(String(x.reps))?'s':'reps'}
function seriesTarget(x,number){const t=String(x.reps).replace(/^de\s*/i,'');let part=t.split('/')[number-1]||t.split('/').at(-1);const n=part.match(/\d+/)?.[0];return n?(Number(n)*(seriesUnit(x)==='s'&&/min/i.test(t)?60:1)):''}
function entriesFor(index){return seriesEntries.filter(e=>e.index===index)}
function previousExercise(name){return data.logs.filter(l=>l.student===student&&l.seriesEntries?.some(e=>e.name===name)).at(-1)?.seriesEntries.filter(e=>e.name===name)||[]}
function seriesRunner(){const exercises=plan(),x=exercises[activeExercise],entries=x?entriesFor(activeExercise):[],number=entries.length+1,all=exercises.length&&done.size===exercises.length;return heading('SESSÃO DE TREINO',blockTitle(),'Registre cada série e acompanhe sua evolução.')+blockChooser()+`<section class="card workout-controls"><div class="row"><div><span class="eyebrow">${workoutStarted?'TREINO EM ANDAMENTO':'PRONTO PARA COMEÇAR?'}</span><h2>${workoutStarted?`${done.size} de ${exercises.length} exercícios concluídos`:'Um exercício de cada vez.'}</h2></div>${workoutStarted?`<strong id="workout-duration">${clockText(Math.floor((Date.now()-workoutStarted)/1000))}</strong>`:`<button class="primary" onclick="startWorkout()" ${exercises.length?'':'disabled'}>▶ Iniciar treino</button>`}</div><p class="note">Descanso automático após cada série. Mantenha o app aberto para receber o alerta.</p></section>${!exercises.length?'<section class="card empty">Seu personal ainda não adicionou exercícios nesta divisão.</section>':!workoutStarted?`<section class="card"><h2>O que vamos treinar</h2>${exercises.map((e,i)=>`<div class="exercise"><span class="num">${i+1}</span><div class="details"><b>${esc(e.name)}</b><p>${e.sets} séries × ${esc(e.reps)} · ${e.weight} kg</p>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div><button onclick="demo(${i})">Ver demonstração</button></div>`).join('')}</section>`:all?'<section class="card session-success"><span class="goal-icon">✓</span><h2>Você concluiu todas as séries!</h2><p>Finalize o registro para salvar cargas, repetições e duração no histórico.</p><button class="primary" onclick="finish()">✓ Treino concluído</button></section>':`<section class="card series-runner"><span class="tag">EXERCÍCIO ${activeExercise+1} DE ${exercises.length}</span><h2>${esc(x.name)}</h2><p>${x.sets} séries · ${esc(x.reps)} previstas · ${x.rest}s de descanso</p>${x.notes?`<p>${esc(x.notes)}</p>`:''}<button onclick="demo(${activeExercise})">▷ Ver demonstração</button>${previousExercise(x.name).length?`<p class="previous-load">Última sessão: ${previousExercise(x.name).map(e=>`${e.reps} ${e.unit==="s"?"seg":"reps"} × ${e.weight} kg`).join(' · ')}</p>`:'<p class="note">Primeiro registro deste exercício. Cada série conta.</p>'}<div class="series-checks">${Array.from({length:x.sets},(_,i)=>`<span class="${i<entries.length?'recorded':''}">${i<entries.length?'✓':i+1}</span>`).join('')}</div>${done.has(activeExercise)?'<p>Exercício concluído. Aguarde o descanso ou toque em Voltar ao exercício.</p>':`<form id="seriesForm" onsubmit="recordSeries(event)"><h3>Série ${number} de ${x.sets}</h3><div class="inline"><label>Carga realizada (kg)<input name="weight" type="number" min="0" max="1000" step="0.5" value="${entries.at(-1)?.weight??x.weight}" required ${restTimer?'disabled':''}></label><label>${seriesUnit(x)==="s"?"Tempo realizado (segundos)":"Repetições realizadas"}<input name="reps" type="number" min="1" max="7200" value="${seriesTarget(x,number)}" required ${restTimer?'disabled':''}></label></div><button class="primary" ${restTimer?'disabled':''}>${restTimer?'Descanso em andamento':'✓ Série concluída'}</button></form>`}<h3 style="margin-top:25px">Séries registradas</h3>${entries.map(e=>`<div class="listrow"><span class="tag">SÉRIE ${e.set}</span><b>${e.reps} ${e.unit==="s"?"seg":"reps"} × ${e.weight} kg</b></div>`).join('')||'<p class="note">Nenhuma série registrada ainda.</p>'}</section>`}`}
window.recordSeries=event=>{event.preventDefault();if(role!=='aluno'||!workoutStarted||restTimer)return;const x=plan()[activeExercise];if(!x||done.has(activeExercise))return;const f=new FormData(event.target),weight=+f.get('weight'),reps=+f.get('reps');if(!Number.isFinite(weight)||weight<0||weight>1000||!Number.isInteger(reps)||reps<1||reps>(seriesUnit(x)==="s"?7200:100))return;seriesEntries.push({index:activeExercise,name:x.name,set:entriesFor(activeExercise).length+1,weight,reps,unit:seriesUnit(x)});if(entriesFor(activeExercise).length>=x.sets)done.add(activeExercise);window.startRest(activeExercise);if(!restTimer&&done.has(activeExercise))activeExercise=Math.min(activeExercise+1,plan().length-1);render()};
const runnerStart=window.startWorkout;window.startWorkout=()=>{if(workoutStarted)return;activeExercise=0;seriesEntries=[];runnerStart()};
const runnerEndRest=window.endRest;window.endRest=()=>{runnerEndRest();if(workoutStarted&&done.has(activeExercise)&&done.size<plan().length)activeExercise=Math.min(activeExercise+1,plan().length-1);if(role==='aluno'&&page==='treinos')render()};
const runnerFinish=window.finish;window.finish=()=>{if(seriesEntries.length===0&&workoutStarted){toast('Registre suas séries antes de concluir.');return}runnerFinish();const form=$('#finishForm');if(!form||!$('#modal').open)return;const submit=form.onsubmit,recorded=seriesEntries.map(e=>({...e})),block=window.currentTrainingBlock,title=blockTitle();form.onsubmit=event=>{const count=data.logs.length;submit(event);if(data.logs.length>count){Object.assign(data.logs.at(-1),{block,title,seriesEntries:recorded});save();seriesEntries=[];activeExercise=0;render()}}};
const runnerSelect=window.selectStudent;window.selectStudent=id=>{if(workoutStarted)return;window.currentTrainingBlock='A';activeExercise=0;seriesEntries=[];runnerSelect(id)};
const runnerLogout=logoutButton.onclick;logoutButton.onclick=()=>{window.currentTrainingBlock='A';activeExercise=0;seriesEntries=[];runnerLogout()};
const upgradedEdit=window.editExercise;window.editExercise=(i,preset)=>{upgradedEdit(i,preset);const x=i===undefined?preset||{}:plan()[i];$('#exerciseForm').insertAdjacentHTML('beforeend',`<label>Vídeo de demonstração (HTTPS, opcional)<input name="video" type="url" value="${esc(x.video||'')}" placeholder="https://…/exercicio.mp4"></label>`);const form=$('#exerciseForm'),submit=form.onsubmit;form.onsubmit=event=>{const video=new FormData(event.target).get('video').trim();if(video&&!/^https:\/\//i.test(video)){event.preventDefault();toast('Use um link HTTPS para o vídeo.');return}const before=JSON.stringify(plan());submit(event);if(JSON.stringify(plan())!==before){const item=plan()[i===undefined?plan().length-1:i];item.video=video;save()}}};
const previousDemo=window.demo;window.demo=index=>{const x=plan()[index];if(!x.video)return previousDemo(index);const url=new URL(x.video),file=/\.(mp4|webm|ogg)$/i.test(url.pathname);modal(`<span class="eyebrow">DEMONSTRAÇÃO DO PERSONAL</span><h2>${esc(x.name)}</h2>${file?`<video controls playsinline preload="metadata" style="width:100%;max-height:360px" src="${esc(x.video)}"></video>`:`<a class="media-link" href="${esc(x.video)}" target="_blank" rel="noopener noreferrer">Abrir vídeo de demonstração ↗</a>`}<p>${x.sets} séries × ${esc(x.reps)} repetições · ${x.rest}s de descanso</p>`) };
function coachPriorityPanel(){const students=visibleStudents(),month=todayKey().slice(0,7),missing=students.filter(s=>missedDays(s.id).length),water=students.filter(s=>waterFor(s.id)<goalsFor(s.id).water),fees=students.filter(s=>feeOverdue(feeFor(s.id,month),month));return `<section class="card coach-priorities"><span class="eyebrow">VISÃO DE PRIORIDADES</span><h2>Quem precisa da sua atenção?</h2><div class="priority-grid"><button onclick="go('inicio')"><strong>${missing.length}</strong><span>Alunos com treinos sem registro</span></button><button onclick="go('evolucao')"><strong>${water.length}</strong><span>Meta de água ainda em andamento</span></button><button onclick="go('financeiro');setFinanceTab('mensal')"><strong>${fees.length}</strong><span>Pagamentos vencidos neste mês</span></button></div><p class="note">São pendências dos registros, não uma confirmação de falta ou de consumo real de água.</p></section>`}
function seriesHistory(){const logs=data.logs.filter(l=>l.student===student&&l.seriesEntries?.length).slice().reverse();return `<section class="card series-history"><h2>Evolução de cargas e repetições</h2>${logs.map(l=>`<details><summary>${new Date(l.date).toLocaleDateString('pt-BR')} · ${esc(l.title||`Treino ${l.block||'A'}`)} · ${l.seriesEntries.length} séries</summary>${l.seriesEntries.map(e=>`<div class="listrow"><div><b>${esc(e.name)}</b><p>Série ${e.set} · ${esc(e.reps)} repetições · ${e.weight} kg</p></div></div>`).join('')}</details>`).join('')||'<p>As cargas e repetições aparecerão após concluir uma sessão com registro de séries.</p>'}</section>`}
const trainingUpgradeRender=render;render=function(){trainingUpgradeRender();if(page==='treinos'){if(role==='aluno'){$('#content').innerHTML=seriesRunner();tickWorkout()}else if(role==='personal')$('#content').children[0].after(Object.assign(document.createElement('section'),{innerHTML:blockChooser()}))}if(page==='inicio'&&role==='personal')$('#content').insertAdjacentHTML('afterbegin',coachPriorityPanel());if(page==='evolucao'&&role!=='adm')$('#content').insertAdjacentHTML('beforeend',seriesHistory())};

